  <script>
    // Seat selector (local fake)
    const seatMap = document.getElementById('seatMap');
    const selectedCount = document.getElementById('selectedCount');
    const availableCount = document.getElementById('availableCount');
    const TOTAL_SEATS = 24;
    let seats = [];

    // initialize seats: simulate some taken seats using deterministic pseudo-random
    function pseudoRand(i){ const seed = 2063204081; return ((seed >> (i%27)) * (i+7)) % 10; }
    for(let i=0;i<TOTAL_SEATS;i++){
      const btn = document.createElement('button'); btn.className='seat available'; btn.textContent = i+1; btn.dataset.index = i;
      const taken = (pseudoRand(i)%7===0); if(taken){ btn.className='seat taken'; }
      btn.addEventListener('click', ()=>{ if(btn.classList.contains('taken')) return; btn.classList.toggle('selected'); updateCounts(); });
      seatMap.appendChild(btn); seats.push(btn);
    }
    function updateCounts(){ const sel = seats.filter(s=>s.classList.contains('selected')).length; const avail = seats.filter(s=>!s.classList.contains('taken')).length; selectedCount.textContent = sel; availableCount.textContent = avail; }
    updateCounts();

    // packing list generator
    const genPack = document.getElementById('genPack'); const packPanel = document.getElementById('packPanel'); const packItems = document.getElementById('packItems');
    genPack.addEventListener('click', ()=>{
      const dur = Number(document.getElementById('duration').value);
      const comfort = document.getElementById('comfort').value;
      const needMat = document.getElementById('needMat').checked;
      const needBlanket = document.getElementById('needBlanket').checked;
      const list = [];
      // base items
      list.push('Water bottle'); list.push('Mask if you prefer');
      if(needMat) list.push('Mat (reserved)'); else list.push('Your mat or towel');
      if(needBlanket) list.push('Blanket'); else list.push('Light throw or long-sleeve layer');
      if(dur>=75) list.push('Small eye-cover (optional)');
      if(comfort==='cozy') list.push('Extra cushion or neck pillow');
      if(comfort==='minimal') list.push('Compact mat and light wrap');
      // local suggestions
      if(seats.filter(s=>s.classList.contains('selected')).length===0) list.push('Reserve at least one seat to finalize');

      // render
      packItems.innerHTML = ''; list.forEach(it=>{ const li=document.createElement('li'); li.textContent = it; packItems.appendChild(li); });
      packPanel.style.display='block';
    });

    // confirm & fake submit
    document.getElementById('confirmBtn').addEventListener('click', ()=>{
      const name = document.getElementById('name').value || 'Guest';
      const email = document.getElementById('email').value || '—';
      const selected = seats.filter(s=>s.classList.contains('selected')).map(s=>Number(s.dataset.index)+1);
      if(selected.length===0){ alert('Please select at least one seat.'); return; }
      // fake confirmation
      alert('Thank you, ' + name + '.\nYou reserved seats: ' + selected.join(', ') + '.\nA confirmation will be sent to ' + email + '.');
      // reset selections
      seats.forEach(s=>s.classList.remove('selected'));
      updateCounts();
    });
  </script>
